// HasCharacter applies the HasEdge predicate on the "character" edge.
func HasCharacter() predicate.CharacterSpellcasting {
	return predicate.CharacterSpellcasting(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, CharacterTable, CharacterColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCharacterWith applies the HasEdge predicate on the "character" edge with a given conditions (other predicates).
func HasCharacterWith(preds ...predicate.Character) predicate.CharacterSpellcasting {
	return predicate.CharacterSpellcasting(func(s *sql.Selector) {
		step := newCharacterStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CharacterSpellcasting) predicate.CharacterSpellcasting {
	return predicate.CharacterSpellcasting(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CharacterSpellcasting) predicate.CharacterSpellcasting {
	return predicate.CharacterSpellcasting(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CharacterSpellcasting) predicate.CharacterSpellcasting {
	return predicate.CharacterSpellcasting(sql.NotPredicates(p))
}
